package leetcode.medium;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import java.util.Arrays;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class OnlineStockSpanTest {

    @Mock
    private Stack<Integer> stack;

    public int[] calculateSpans(int[] prices) {
        return new OnlineStockSpan().calculateSpans(prices);
    }

    @Test
    public void next_ReturnsNextPrice() {
        when(stack.isEmpty()).thenReturn(true);
        when(stack.push(10)).thenReturn(false);
        when(stack.peek()).thenReturn(0);

        int result = new OnlineStockSpan().next(5);
        assertEquals(6, result);
    }

    @Test
    public void next_PushesToStackIfPriceDecreases() {
        when(stack.isEmpty()).thenReturn(true);
        when(stack.push(10)).thenReturn(false);
        when(stack.peek()).thenReturn(0);

        new OnlineStockSpan().next(5);
        verify(stack).push(6);
    }

    @Test
    public void next_PushesToStackIfPriceIsSame() {
        when(stack.isEmpty()).thenReturn(true);
        when(stack.push(10)).thenReturn(false);
        when(stack.peek()).thenReturn(0);

        new OnlineStockSpan().next(5);
        verify(stack).push(6);
    }

    @Test
    public void next_ThrowsExceptionWhenStackNotEmpty() {
        when(stack.isEmpty()).thenReturn(false);
        when(stack.pop()).thenReturn(10);

        assertThrows(NullPointerException.class, () -> new OnlineStockSpan().next(5));
    }

    @Test
    public void calculateSpans_ReturnsCorrectSpans() {
        int[] prices = {10, 7, 5, 8, 11, 9};
        int[] result = new OnlineStockSpan().calculateSpans(prices);
        assertEquals(new int[]{1, 2, 3, 4, 5, 6}, result);
    }

    @Test
    public void calculateSpans_ReturnsCorrectSpansForEmptyArray() {
        int[] prices = {};
        int[] result = new OnlineStockSpan().calculateSpans(prices);
        assertEquals(new int[]{0}, result);
    }

    @Test
    public void calculateSpans_ThrowsExceptionWhenPricesIsNegative() {
        int[] prices = {-10, -7, -5, -8, -11, -9};
        assertThrows(NullPointerException.class, () -> new OnlineStockSpan().calculateSpans(prices));
    }
}
```
